mapper.select:
select *
from request_dedup
where house_id = #{houseId}
  and user_id = #{userId}
  and api = #{api}
  and request_id = #{requestId}
limit 1

mapper.update:
update request_dedup
set status = #{status},
    error_message = #{errorMessage},
    update_time = now()
where house_id = #{houseId}
  and user_id = #{userId}
  and api = #{api}
  and request_id = #{requestId}

update request_dedup
set status = #{status},
    error_message = null,
    response_payload = #{responsePayload},
    update_time = now()
where house_id = #{houseId}
  and user_id = #{userId}
  and api = #{api}
  and request_id = #{requestId}
